                  labelText: context.l10n.adminText('worker.name'),
                ),
              ),
              const SizedBox(height: 12),
              _WorkerLevelPickerField(
                value: _selectedLevel,
                onTap: _pickLevel,
              ),
              const SizedBox(height: 14),
              FilledButton.icon(
                onPressed: _saving ? null : _save,
                icon: _saving
                    ? const SizedBox.square(
                        dimension: 18,
